-- Itsu:UI: controller mode, JarStick folded in.
-- the JarStick files in Modules\Controller are generated by sync_jarstick.py, each one
-- drops a function in ns.jsParts. this runs them with JarStick's own namespace and
-- draws its settings as JarForever pages (Controller > Controls, Layout, ...)

local _, ns = ...

local GROUP = "Controller"
local PAGES = { "Controls", "Layout", "Bars", "Menus", "Profiles" }

ns.RegisterModule("controller", "Controller", function()
    local js = {
        loadHooks = {},
        acct = ns.db.controller,
        charDB = ns.char.controller,
    }
    ns.js = js
    for _, part in ipairs(ns.jsParts or {}) do
        part(js, "JarStick")
    end
    -- jarforever's own ADDON_LOADED is already running, replay JarStick's now every file is in
    for _, fn in ipairs(js.loadHooks) do
        fn()
    end

    -- JarStick calls these when something it owns changes (dragging, profiles)
    js.OpenSettings = function() ns.OpenConfig("Controls") end
    js.RefreshConfig = function()
        for _, name in ipairs(PAGES) do ns.RefreshPanel(name) end
    end

    -- small helpers -------------------------------------------------------------

    local function Key(key, after)
        return function() return js.db[key] end, function(v)
            js.db[key] = v
            if after then after() end
        end
    end

    local function Fmt(decimals)
        return function(v) return string.format("%." .. decimals .. "f", v) end
    end

    -- dropdown over { {label, value}, ... }, or a function returning that
    local function Choice(b, text, options, get, set)
        local function Opts() return type(options) == "function" and options() or options end
        b:Dropdown(text, function()
            for _, o in ipairs(Opts()) do
                if o[2] == get() then return o[1] end
            end
            return tostring(get())
        end, function(_, root)
            for _, o in ipairs(Opts()) do
                root:CreateRadio(o[1], function() return get() == o[2] end, function()
                    set(o[2])
                    b:Refresh()
                end)
            end
        end)
    end

    local function PageOptions(only)
        local list = {}
        for _, p in ipairs(js.PAGES) do
            if not only or only[p.page] then
                list[#list + 1] = { p.name .. "  (slots " .. p.slots .. ")", p.page }
            end
        end
        return list
    end
    -- the real bars, no stance / vehicle pages
    local BAR_PAGES = { [1] = true, [2] = true, [3] = true, [4] = true, [5] = true, [6] = true, [13] = true, [14] = true, [15] = true }

    -- controls ------------------------------------------------------------------

    ns.RegisterPanel(22.1, "Controls", function(b)
        local db = js.db
        b:Header("Sticks")
        b:Toggle("Mouse mode button", { { "R3", "R3" }, { "L3", "L3" } },
            function() return db.mouseStick end,
            function(v) db.mouseStick = v; js.ApplyBindings() end)
        b:Note("The other stick click jumps. In mouse mode the right stick moves the cursor, R1 left clicks and L1 right clicks.")

        b:Header("Camera")
        b:Check("Invert camera X", Key("invertX", js.ApplyCamera))
        b:Check("Invert camera Y", Key("invertY", js.ApplyCamera))
        b:Check("Camera-locked movement  (stick back = backpedal)", Key("turnAlways", js.ApplyCamera))
        b:Note("Off is Blizzard's default: out of combat pulling back turns you around and runs forward.")
        b:Slider("Camera speed", 0.25, 3, 0.05, function() return db.cameraSpeed end,
            function(v) db.cameraSpeed = v; js.ApplyCamera() end, Fmt(2))
        b:Check("Action cam", Key("actionCam", js.ApplyActionCam))
        b:Toggle("Action cam mode", { { "Basic", "basic" }, { "Full", "full" } },
            function() return db.actionCamMode end,
            function(v)
                db.actionCamMode = v
                if db.actionCam then js.ApplyActionCam() end
            end)
        b:Note("Same as /console actioncam basic or full. Applied on login while ticked, turned off again when unticked. Turns off Keep Character Centered while on.")

        b:Header("Select + L2 / R2 zoom")
        b:Slider("Zoom speed", 0.25, 3, 0.05, function() return db.zoomSpeed end,
            function(v) db.zoomSpeed = v end, Fmt(2))
        b:Check("Flip zoom direction  (L2 zooms in)", Key("zoomFlip"))

        b:Header("Interact")
        b:Check("Center crosshair  (the X prompt under it shows either way)", Key("reticle", js.UpdateReticle))
        b:Slider("Crosshair and prompt size", 0.5, 3, 0.1, function() return db.reticleScale end,
            function(v) db.reticleScale = v; js.UpdateReticle() end, Fmt(1))
        b:Check("X interacts in combat too", Key("interactInCombat", js.ApplyInteract))
        b:Check("Blizzard's hand marker on the object you're facing", Key("objectIcon", js.ApplyObjectIcon))
        b:Note("X uses the NPC or object in front of you. With a gossip, quest, loot or bag window open the pad drives that window: a legend shows what X / A / B / Y do and the d-pad moves the cursor.")

        b:Header("Controller")
        Choice(b, "Use controller", function()
            local list = {
                { "Auto: one recognized pad, ignore a generic twin of it", "" },
                { "All controllers combined (Blizzard default)", "combined" },
            }
            for _, e in ipairs(js.DeviceList()) do
                list[#list + 1] = { e.name .. (e.generic and "  (generic map)" or ""), e.name }
            end
            return list
        end, function() return db.device end, function(v) db.device = v; js.ApplyDevice() end)
        b:Buttons({ { "Pad Report", js.PadReport, 160 } })
        b:Note("Prints what the pad sends to chat (also /jf pad). A pad on a wireless dongle can show up twice, combined input then doubles every press.")
    end, GROUP)

    -- layout --------------------------------------------------------------------

    ns.RegisterPanel(22.2, "Layout", function(b)
        local db = js.db
        local halfW, halfH = math.floor(UIParent:GetWidth() / 2), math.floor(UIParent:GetHeight() / 2)
        local function Pos(side, axis)
            return function() return db[side][axis] or 0 end, function(v)
                db[side][axis] = v
                if db.mirror then js.MirrorFrom(side) end
                js.ApplyLayout()
            end
        end
        b:Header("Clusters")
        b:Check("Lock clusters", Key("locked", js.ApplyLock))
        b:Note("Unlocked, drag them with the mouse. On the pad: L2 + R2 + X unlocks and the left stick moves them, X again locks.")
        b:Check("Mirror the right cluster to the left one", Key("mirror", function()
            if db.mirror then
                js.MirrorFrom("left")
                js.ApplyLayout()
            end
        end))
        b:Check("Show pad glyphs on the buttons", Key("showGlyphs", js.RefreshGlyphs))
        b:Slider("Scale", 0.5, 2, 0.05, function() return db.scale end,
            function(v) db.scale = v; js.ApplyLayout() end, Fmt(2))
        local lx, sx = Pos("left", "x")
        b:Slider("Left cluster X  (from screen center)", -halfW, halfW, 1, lx, sx, Fmt(0))
        local ly, sy = Pos("left", "y")
        b:Slider("Left cluster Y  (from screen center)", -halfH, halfH, 1, ly, sy, Fmt(0))
        local rx, srx = Pos("right", "x")
        b:Slider("Right cluster X  (only with mirror off)", -halfW, halfW, 1, rx, srx, Fmt(0))
        local ry, sry = Pos("right", "y")
        b:Slider("Right cluster Y  (only with mirror off)", -halfH, halfH, 1, ry, sry, Fmt(0))
        b:Buttons({ { "Reset Positions", function()
            js.ResetPositions()
            b:Refresh()
        end, 160 } })

        b:Header("Book")
        b:Slider("Spellbook and talents window scale", 0.8, 2, 0.05, function() return db.configScale end,
            function(v) db.configScale = v end, Fmt(2))
    end, GROUP)

    -- bars ----------------------------------------------------------------------

    ns.RegisterPanel(22.3, "Bars", function(b)
        local db = js.db
        local function Bar(key) return function() return db.bars[key] end, function(v) db.bars[key] = v; js.RefreshPageDriver() end end
        local function Page(key) return function() return db.pages[key] end, function(v) db.pages[key] = v; js.RefreshPageDriver() end end
        b:Header("Bars")
        b:Check("Lock action bars  (Blizzard setting, hold the pickup key to drag off)", js.GetLockActionBars, js.SetLockActionBars)
        b:Check("Hide Blizzard bars 1-3  (showing them again needs /reload)", Key("hideBlizzard", js.ToggleHideBlizzard))
        b:Note("A / B / X / Y are slots 1-4 of the picked bar, L2 + face button 5-8, R2 + face button 9-12. The d-pad picks the bar and it stays picked. Drag spells, items and macros onto the face buttons, hold L2 or R2 while dropping to fill 5-8 or 9-12. L1 / R1 tab target (L1 enemy, R1 friend).")

        b:Header("Party layer  (hold R1)")
        b:Note("Tap R1 to tab through friends. Hold R1 and the d-pad targets party members 2 to 5. R1 + L1 together (either order) opens the party ring: point the right stick at someone and they're targeted right away, let go of either to close it. In a raid the ring shows your own group.")
        Choice(b, "Party health colors on the d-pad",
            { { "Border and fill", "both" }, { "Fill only", "fill" }, { "Border only", "border" }, { "Off", "off" } },
            Key("partyHealth"))
        b:Note("Green 60%+, yellow 25-59%, red under 25%, black when dead. The border goes blue / purple / brown for a dispellable debuff when Blizzard lets addons read auras.")

        b:Header("Paging")
        b:Note("D-pad up is always Action Bar 1, it follows forms and stealth like the stock bar.")
        local bars, all = PageOptions(BAR_PAGES), PageOptions()
        local g, s
        g, s = Bar("PADDRIGHT"); Choice(b, "D-pad right shows", bars, g, s)
        g, s = Bar("PADDDOWN"); Choice(b, "D-pad down shows", bars, g, s)
        g, s = Bar("PADDLEFT"); Choice(b, "D-pad left shows", bars, g, s)
        g, s = Page("sel"); Choice(b, "Select held shows", bars, g, s)
        g, s = Page("b1"); Choice(b, "Bonus bar 1  (cat form, stealth)", all, g, s)
        g, s = Page("b2"); Choice(b, "Bonus bar 2  (tree of life)", all, g, s)
        g, s = Page("b3"); Choice(b, "Bonus bar 3  (bear form)", all, g, s)
        g, s = Page("b4"); Choice(b, "Bonus bar 4  (moonkin)", all, g, s)
        g, s = Page("b5"); Choice(b, "Bonus bar 5", all, g, s)
        b:Note("Bonus bars only apply while Action Bar 1 is picked. Vehicles, possession and override bars take over the face buttons on any bar.")
    end, GROUP)

    -- menus ---------------------------------------------------------------------

    ns.RegisterPanel(22.4, "Menus", function(b)
        local db = js.db
        b:Header("Select menu  (tap Select)")
        b:Note("Tap Select for the menu: d-pad picks, X opens, B or another tap closes. Out of combat only. A window opened from it turns the cursor on, closing it turns it off. Holding Select still pages the face buttons to the bar picked on the Bars page (Action Bar 6 by default), and L2 / R2 zoom while it is held.")
        b:Note("Start opens the game menu: d-pad picks, X selects, B goes back to the game. On the flight map the d-pad hops between flight points, Y switches to an A-Z list, X flies.")
        b:Note("Spellbook and Talents in the menu open Blizzard's own windows. The pad book is L2 + R2 + A (spells) and L2 + R2 + Y (talents). X picks a spell up, then press a face button to put it there. The d-pad switches bars, hold L2 or R2 for slots 5-12, L1 or R1 to drop it into a spare grid. Start cancels. Out of combat only.")

        b:Header("Special layer  (hold L2 + R2)")
        b:Note("Fixed, nothing pages over it: the d-pad toggles a raid marker on your target, A opens the pad spellbook, Y the talents, X unlocks the clusters, B summons a favorite mount or dismounts.")
        local names = { "Star", "Circle", "Diamond", "Triangle", "Moon", "Square", "Cross", "Skull" }
        local marks = {}
        for i, n in ipairs(names) do
            marks[i] = { "|TInterface\\TargetingFrame\\UI-RaidTargetingIcon_" .. i .. ":16|t  " .. n, i }
        end
        for _, d in ipairs({ { "PADDUP", "up" }, { "PADDRIGHT", "right" }, { "PADDLEFT", "left" }, { "PADDDOWN", "down" } }) do
            Choice(b, "L2 + R2 + d-pad " .. d[2], marks,
                function() return db.marks[d[1]] end,
                function(v) db.marks[d[1]] = v; js.ApplyMarks() end)
        end

        b:Header("Bags")
        b:Note("With the bags open (out of combat) the d-pad walks the items, X uses or equips the picked one (sells it at a vendor), Y deletes it after a confirm that X accepts, B closes.")

        b:Header("Spare bar grids  (L2 + R2 + L1 or R1)")
        b:Note("L2 + R2 + L1 opens a 3x4 grid of Action Bar 4 above the L1 box, L2 + R2 + R1 the same with Action Bar 5 above R1. They stay open until toggled again. While a grid is open the plain d-pad walks it and X uses the picked slot, L2 or R2 + d-pad still switches bars.")
    end, GROUP)

    -- profiles ------------------------------------------------------------------

    ns.RegisterPanel(22.5, "Profiles", function(b)
        b:Header("Profiles")
        b:Text(function()
            local cur = js.CurrentProfile()
            return cur and ("Profile: " .. cur) or "Profile: none, settings live on this character"
        end, ns.UI.text)
        local row = b:Input("Profile name", js.CurrentProfile)
        b:Buttons({
            { "Save", function() js.SaveProfile(row.box:GetText()); b:Refresh() end, 120 },
            { "Delete", function() js.DeleteProfile(row.box:GetText()); b:Refresh() end, 120 },
        })
        b:Dropdown("Load a profile", function() return "Pick one..." end, function(_, root)
            local names = js.ProfileNames()
            if #names == 0 then
                root:CreateTitle("No saved profiles")
                return
            end
            for _, name in ipairs(names) do
                root:CreateButton(name, function()
                    js.LoadProfile(name)
                    b:Refresh()
                end)
            end
        end)
        b:Note("Controller settings save per character. Save them as a named profile to reuse on other characters.")

        b:Header("Commands")
        b:Note("/jf pad | ui | debug | ring | book | talents | mouse | lock | unlock | reset | resetall\n/jf save <name> | load <name> | delete <name> | list")

        b:Header("Reset")
        b:Buttons({
            { "Reset Controller Settings", function() js.ResetAll(); b:Refresh() end, 220 },
            { "Blizzard Pad Defaults", js.ResetPadCVars, 200 },
        })
        b:Note("The first puts Blizzard's gamepad settings back, then the controller defaults on top: positions, paging, camera, all of it. Profiles are kept. The second only resets Blizzard's gamepad settings.")
    end, GROUP)

    -- enemy targeted, show its tooltip in blizzards default spot (bottom right)
    local tipOwner = CreateFrame("Frame", nil, UIParent)

    local function ShowTargetTip()
        if not UnitExists("target") or not UnitCanAttack("player", "target") then
            if GameTooltip:IsOwned(tipOwner) then GameTooltip:Hide() end
            return
        end
        -- something else is using the tooltip, wait for it to hide
        if GameTooltip:IsShown() and not GameTooltip:IsOwned(tipOwner) then return end
        GameTooltip_SetDefaultAnchor(GameTooltip, tipOwner)
        GameTooltip:SetUnit("target")
    end

    local tipEvents = CreateFrame("Frame")
    tipEvents:RegisterEvent("PLAYER_TARGET_CHANGED")
    tipEvents:RegisterUnitEvent("UNIT_FACTION", "target")
    tipEvents:SetScript("OnEvent", ShowTargetTip)
    -- a mouseover or button tooltip took it over, bring ours back once thats gone
    GameTooltip:HookScript("OnHide", function() C_Timer.After(0, ShowTargetTip) end)
end)
